used = set()
for f in sorted(glob.glob(D + '[bc][12]_words.txt')):
    if f.endswith('b1_words.txt'): continue
    out = []
    for l in open(f, encoding='utf-8'):
        if l.startswith('#') or not l.strip(): out.append(l); continue
        c = l.rstrip('\n').split('|')
        while len(c) < 5: c.append('')
        k = c[0].strip()
        if k in ADD:
            used.add(k)
            have = [x.strip() for x in c[2].split(',') if x.strip()]
            low = {h.lower().lstrip('~') for h in have} | {k.lower()}
            have += [x for x in ADD[k] if x.lower() not in low]
            c[2] = ','.join(have)
        out.append('|'.join(c) + '\n')
    open(f, 'w', encoding='utf-8').writelines(out)
print('touched', len(used), 'missing', sorted(set(ADD) - used))
